import PropTypes from "prop-types";
import React from "react";
import formatLabel from "../../results/formatLabel";
import type { ResultsBayesFunding } from "../../../types/cards/card";

/**
 * Render a Funnelback result as a Bayes funding card.
 *
 * @param {object} props React props.
 * @return {object} - React component.
 */

function Finder__Bayes__Funding(props: ResultsBayesFunding) {
  const 
    cardHeading = props.query.query || props.details.title ? (<h3 className="card__heading">
                        <a href={props.details.liveUrl}>
                            {props.query.query
                                ? formatLabel(props.details.title, props.query.query)
                            : props.details.title}
                        </a>
                    </h3>) : null,
    subtitle =
      (props.details?.listMetadata?.type?.[0]) 
        ||
      null,
    description = props.details?.listMetadata?.c?.[0] && (
        <p className="card__description">
          {props.query.query
            ? formatLabel(props.details.listMetadata.c[0], props.query.query)
            : props.details.listMetadata.c[0]}
        </p>
      ),
    fundingStatus = props.details?.listMetadata?.fStatus?.[0] && (
        <p className="card__tag">
          <span className="icon"><span
            className="card--bayes-funding__icon"
            aria-hidden="true"
          /></span>
          {" "}
          <span>Funding status:</span>{" "}
          <span><strong>{props.details.listMetadata.fStatus[0]}</strong></span>
        </p>
      ),
      region = props.details?.listMetadata?.region && (
        <p className="card__tag">
          <span>Region:</span>{" "}
          <span><strong>{props.details.listMetadata.region[0]}</strong></span>
        </p>
      ),
      programme = props.details?.listMetadata?.programme && (
        <p className="card__tag">
          <span>Programme:</span>{" "}
          <span><strong>{props.details.listMetadata.programme[0]}</strong></span>
        </p>
      );

  return (
    <li className="card card--bayes-funding">
        <div className="wrapper--card__label__details">
          <div className="card__details__text">
            {cardHeading}
            <p className="card__type">
              {props.query.query && subtitle
                ? formatLabel(subtitle, props.query.query)
                : subtitle}
            </p>
            {description}
            {programme || region ? (
                <div className="card--bayes-funding__programme-region">{programme}{region}</div>
                ) : null}
            {fundingStatus}
          </div>
        </div>
    </li>
  );
}

Finder__Bayes__Funding.propTypes = {
  details: PropTypes.object,
  query: PropTypes.object,
};

export default Finder__Bayes__Funding;
